/* eslint-disable */

/**
 * grid(ratios, containerWidth, targetWidth, gap) → {containerHeight, boxes}
 *
 * Fixed columns with aligned row starts and variable photo heights.
 */
export function grid(ratios: Float64Array, container_width: number, target_width: number, gap: number): any;

/**
 * justified(ratios, containerWidth, targetRowHeight, spacing) → {containerHeight, boxes}
 *
 * Lays out photos in rows where every photo shares the same height and all
 * photos together fill the container width. Greedy Flickr algorithm.
 */
export function justified(ratios: Float64Array, container_width: number, target_row_height: number, spacing: number): any;

/**
 * masonry(ratios, containerWidth, targetWidth, gap) → {containerHeight, boxes}
 *
 * Places each photo into the shortest column (Pinterest style).
 */
export function masonry(ratios: Float64Array, container_width: number, target_width: number, gap: number): any;

/**
 * square(ratios, containerWidth, targetSize, gap) → {containerHeight, boxes}
 *
 * Places all photos as uniform squares. Aspect ratios are ignored.
 */
export function square(ratios: Float64Array, container_width: number, target_size: number, gap: number): any;

export type InitInput = RequestInfo | URL | Response | BufferSource | WebAssembly.Module;

export interface InitOutput {
    readonly memory: WebAssembly.Memory;
    readonly grid: (a: number, b: number, c: number, d: number, e: number) => any;
    readonly justified: (a: number, b: number, c: number, d: number, e: number) => any;
    readonly masonry: (a: number, b: number, c: number, d: number, e: number) => any;
    readonly square: (a: number, b: number, c: number, d: number, e: number) => any;
    readonly __wbindgen_externrefs: WebAssembly.Table;
    readonly __wbindgen_malloc: (a: number, b: number) => number;
    readonly __wbindgen_start: () => void;
}

export type SyncInitInput = BufferSource | WebAssembly.Module;

/**
 * Instantiates the given `module`, which can either be bytes or
 * a precompiled `WebAssembly.Module`.
 *
 * @param {{ module: SyncInitInput }} module - Passing `SyncInitInput` directly is deprecated.
 *
 * @returns {InitOutput}
 */
export function initSync(module: { module: SyncInitInput } | SyncInitInput): InitOutput;

/**
 * If `module_or_path` is {RequestInfo} or {URL}, makes a request and
 * for everything else, calls `WebAssembly.instantiate` directly.
 *
 * @param {{ module_or_path: InitInput | Promise<InitInput> }} module_or_path - Passing `InitInput` directly is deprecated.
 *
 * @returns {Promise<InitOutput>}
 */
export default function __wbg_init (module_or_path?: { module_or_path: InitInput | Promise<InitInput> } | InitInput | Promise<InitInput>): Promise<InitOutput>;
